package com.mall.entity;
import com.baomidou.mybatisplus.annotation.*; import lombok.Data; import java.io.Serializable; import java.time.LocalDateTime;
@Data @TableName("cart") public class Cart implements Serializable { @TableId(type=IdType.AUTO) private Long id; private Long userId; private Long productId; private Long skuId; private Integer quantity; private Integer selected; @TableField(fill=FieldFill.INSERT) private LocalDateTime createTime; @TableField(fill=FieldFill.INSERT_UPDATE) private LocalDateTime updateTime; @TableLogic @TableField(fill=FieldFill.INSERT) private Integer deleted; }
